"use client";

import { parseWorkbookFromNotice, type ParsedExamRecord } from "@/lib/exams/parseWorkbook";
import { openExamPageInExtension, requestExamSync } from "@/lib/extensionBridge";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { useEffect, useMemo, useState } from "react";

const DB_NAME = "mydtu-exams-db";
const STORE = "records";

async function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, 1);

    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) {
        db.createObjectStore(STORE, { keyPath: "id" });
      }
    };

    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function saveRecords(records: ParsedExamRecord[]) {
  const db = await openDB();
  const tx = db.transaction(STORE, "readwrite");
  const store = tx.objectStore(STORE);

  for (const r of records) store.put(r);

  return new Promise<void>((resolve) => {
    tx.oncomplete = () => resolve();
  });
}

async function loadRecords(): Promise<ParsedExamRecord[]> {
  const db = await openDB();
  const tx = db.transaction(STORE, "readonly");
  const store = tx.objectStore(STORE);

  return new Promise((resolve) => {
    const req = store.getAll();
    req.onsuccess = () => resolve(req.result || []);
  });
}

function normalizeText(value: unknown) {
  return String(value ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/đ/g, "d")
    .replace(/Đ/g, "D")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeCompact(value: unknown) {
  return normalizeText(value).replace(/[^a-z0-9]/g, "");
}

function tokenizeQuery(query: string) {
  return query
    .split(/[,;\n]+/)
    .map((p) => p.trim())
    .filter(Boolean)
    .map((raw) => ({
      raw,
      loose: normalizeText(raw),
      compact: normalizeCompact(raw)
    }));
}

function compareDateTime(a: ParsedExamRecord, b: ParsedExamRecord) {
  const av = `${a.examDate || "9999"} ${a.startTime || "23:59"}`;
  const bv = `${b.examDate || "9999"} ${b.startTime || "23:59"}`;
  return av.localeCompare(bv);
}

function formatDate(date: string | null) {
  if (!date) return "Chưa rõ ngày";
  const d = new Date(date + "T00:00");
  return d.toLocaleDateString("vi-VN");
}

function getInitialPlan(searchParams: ReturnType<typeof useSearchParams>) {
  const plan = searchParams.get("plan");
  if (plan === "tentative" || plan === "official") return plan;
  return "all";
}

export default function ExamsPage() {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const [records, setRecords] = useState<ParsedExamRecord[]>([]);
  const [query, setQuery] = useState("");
  const [planFilter, setPlanFilter] = useState<"all" | "tentative" | "official">(
    getInitialPlan(searchParams)
  );
  const [syncing, setSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadRecords().then(setRecords);
  }, []);

  const tokens = useMemo(() => tokenizeQuery(query), [query]);

  const filtered = useMemo(() => {
    let next = [...records];

    if (planFilter !== "all") {
      next = next.filter((r) => r.planType === planFilter);
    }

    if (tokens.length) {
      next = next.filter((r) => {
        const loose = [
          r.courseCode,
          r.courseName,
          r.studentId,
          r.studentName,
          r.classCourse,
          r.classStudent,
          r.examDate,
          r.room
        ].map(normalizeText);

        const compact = [
          r.courseCode,
          r.studentId,
          r.classCourse
        ].map(normalizeCompact);

        return tokens.some((t) =>
          loose.some((v) => v.includes(t.loose)) ||
          compact.some((v) => v.includes(t.compact))
        );
      });
    }

    next.sort(compareDateTime);
    return next;
  }, [records, tokens, planFilter]);

  const grouped = useMemo(() => {
    const map = new Map<string, ParsedExamRecord[]>();

    for (const r of filtered) {
      const key = r.examDate || "unknown";
      if (!map.has(key)) map.set(key, []);
      map.get(key)!.push(r);
    }

    return Array.from(map.entries());
  }, [filtered]);

  const stats = useMemo(() => {
    const official = records.filter((r) => r.planType === "official").length;
    const tentative = records.filter((r) => r.planType === "tentative").length;

    return {
      total: records.length,
      official,
      tentative,
      courses: new Set(records.map((r) => r.courseCode)).size
    };
  }, [records]);

  function updatePlanFilter(value: "all" | "tentative" | "official") {
    setPlanFilter(value);

    const next = new URLSearchParams(searchParams.toString());

    if (value === "all") next.delete("plan");
    else next.set("plan", value);

    const qs = next.toString();

    router.replace(qs ? `${pathname}?${qs}` : pathname);
  }

  async function handleSync() {
    setSyncing(true);
    setError(null);

    try {
      const res = await requestExamSync({
        maxPages: 3,
        maxItems: 40
      });

      if (!res.ok) {
        setError(res.error || "Extension error");
        return;
      }

      const parsed: ParsedExamRecord[] = [];

      await Promise.all(
        res.payload.notices.map(async (notice) => {
          const rows = parseWorkbookFromNotice(notice);
          parsed.push(...rows);
        })
      );

      const deduped = Array.from(
        new Map(parsed.map((r) => [r.id, r])).values()
      ).sort(compareDateTime);

      setRecords(deduped);

      await saveRecords(deduped);
    } catch (e) {
      setError(String((e as Error)?.message || e));
    } finally {
      setSyncing(false);
    }
  }

  async function handleOpenPdaotao() {
    const res = await openExamPageInExtension();
    if (!res.ok) {
      window.open("https://pdaotao.duytan.edu.vn/EXAM_LIST/?page=1&lang=VN", "_blank");
    }
  }

  return (
    <div className="space-y-6">

      <section className="app-section p-6">

        <div className="flex justify-between items-center">

          <div>
            <div className="text-3xl font-bold">Danh sách thi</div>
            <div className="text-sm app-text-muted">
              Đồng bộ và tìm kiếm lịch thi DTU
            </div>
          </div>

          <div className="flex gap-2">

            <button onClick={handleOpenPdaotao} className="app-btn">
              Mở pdaotao
            </button>

            <button
              onClick={handleSync}
              disabled={syncing}
              className="app-btn-primary"
            >
              {syncing ? "Đang đồng bộ..." : "Đồng bộ"}
            </button>

          </div>

        </div>

        <div className="mt-5 grid gap-3 xl:grid-cols-[1.6fr_220px]">

          <label htmlFor="exam-search" className="sr-only">
            Tìm kiếm lịch thi
          </label>

          <input
            id="exam-search"
            className="app-input"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="GLY291, MTH383, mã SV..."
          />

          <label htmlFor="exam-plan" className="sr-only">
            Lọc loại lịch thi
          </label>

          <select
            id="exam-plan"
            className="app-input"
            value={planFilter}
            onChange={(e) =>
              updatePlanFilter(e.target.value as "all" | "tentative" | "official")
            }
          >
            <option value="all">Tất cả</option>
            <option value="official">Chính thức</option>
            <option value="tentative">Dự kiến</option>
          </select>

        </div>

      </section>

      <section className="space-y-4">

        {grouped.map(([dateKey, items]) => (
          <div key={dateKey} className="app-section">

            <div className="border-b px-5 py-3">

              <div className="text-lg font-semibold">
                {formatDate(dateKey)}
              </div>

              <div className="text-sm app-text-muted">
                {items.length} bản ghi
              </div>

            </div>

            <div className="overflow-x-auto">

              <table className="w-full text-sm">

                <thead>

                  <tr className="border-b">

                    <th className="px-4 py-3">Loại</th>
                    <th className="px-4 py-3">Môn</th>
                    <th className="px-4 py-3">Giờ</th>
                    <th className="px-4 py-3">Phòng</th>
                    <th className="px-4 py-3">Sinh viên</th>

                  </tr>

                </thead>

                <tbody>

                  {items.map((r) => (

                    <tr key={r.id} className="border-b">

                      <td className="px-4 py-3">
                        {r.planType === "official" ? "Chính thức" : "Dự kiến"}
                      </td>

                      <td className="px-4 py-3">
                        {r.courseCode}
                      </td>

                      <td className="px-4 py-3">
                        {r.startTime || "—"}
                      </td>

                      <td className="px-4 py-3">
                        {r.room || "—"}
                      </td>

                      <td className="px-4 py-3">
                        {r.studentName}
                      </td>

                    </tr>

                  ))}

                </tbody>

              </table>

            </div>

          </div>
        ))}

      </section>

    </div>
  );
}